public static NVHcmESSChangeLog insertRef(RefTableId _refTableId, RefRecId _refRecId)
{
    NVHcmESSChangeLog changeLog;

    select firstonly changeLog
        where changeLog.RefTableId  == _refTableId
            && changeLog.RefRecId   == _refRecId
            && changeLog.Processed  == NoYes::No;

    if(changeLog.RecId == 0)
    {
        changeLog.RefTableId    = _refTableId;
        changeLog.RefRecId      = _refRecId;

        changeLog.insert();
    }

    return changeLog;
}

[SysClientCacheDataMethod(true)]
public display TableName refTableName()
{
    return tableId2PName(this.RefTableId);
}

[SysClientCacheDataMethod(true)]
public display str refDocumentId()
{
    str docuRef = "";

    if(this.RefTableId == tableNum(NVTrvWorkerExpenseRequest))
    {
        docuRef = NVTrvWorkerExpenseRequest::find(this.RefRecId).RequestId;
    }
    else if(this.RefTableId == tableNum(NVTimeSheetLines))
    {
        NVTimeSheetLines timeSheetLines = NVTimeSheetLines::findRecId(this.RefRecId);
        NvTimeSheetHeader timeSheetHeader = timeSheetLines.timeSheetHeader();
        docuRef = strFmt("%1 - %2 - %3", timeSheetHeader.PayCycleId, timeSheetHeader.StartDate, HcmWorker::find(timeSheetLines.Worker).name());
    }

    return docuRef;
}
